class BoundedBuffer<T> {

    private final Queue<T> queue = new LinkedList<>();
    private final int capacity;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull  = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    void put(T item) throws InterruptedException {
        lock.lock();                                  // step 1: acquire the lock
        try {
            while (queue.size() == capacity) {       // step 2: check condition
                notFull.await();                       // step 2b: release lock + sleep, as ONE action
            }                                          // step 5: re-check happens because this is a while, not an if
            queue.add(item);                          // condition true — safe to proceed
            notEmpty.signal();                       // step 3: wake a sleeping consumer
        } finally { lock.unlock(); }
    }

    T take() throws InterruptedException {
        lock.lock();
        try {
            while (queue.isEmpty()) {
                notEmpty.await();
            }
            T item = queue.poll();
            notFull.signal();                        // wake a sleeping producer
            return item;
        } finally { lock.unlock(); }
    }
}

