#include <bits/stdc++.h>
using namespace std;

template <typename T>
class BoundedBuffer {
    deque<T> queue;
    int capacity;
    mutex mtx;
    condition_variable notFull, notEmpty;
public:
    BoundedBuffer(int capacity) : capacity(capacity) {}

    void put(T item) {
        unique_lock<mutex> lock(mtx);                       // step 1: acquire the lock
        notFull.wait(lock, [&]() { return (int)queue.size() < capacity; });  // step 2+5: wait releases lock, re-checks on wake
        queue.push_back(item);                              // condition true, safe to proceed
        notEmpty.notify_one();                               // step 3: wake a sleeping consumer
    }

    T take() {
        unique_lock<mutex> lock(mtx);
        notEmpty.wait(lock, [&]() { return !queue.empty(); });
        T item = queue.front();
        queue.pop_front();
        notFull.notify_one();                                // wake a sleeping producer
        return item;
    }
};

int main() {
    BoundedBuffer<int> buffer(2);

    buffer.put(1);
    buffer.put(2);
    cout << "Buffer filled with 2 items" << endl;

    cout << "Took: " << buffer.take() << endl;
    cout << "Took: " << buffer.take() << endl;
    return 0;
}

