import threading


class Connection:
    def __init__(self, conn_id):
        self.id = conn_id


class ConnectionPool:
    def __init__(self):
        # starts with 10 permits, at most 10 connections checked out at once
        self.permits = threading.Semaphore(10)
        self.next_id = 0

    def acquire(self):
        self.permits.acquire()   # decrements the counter; sleeps if it would go below 0
        return self._create_or_reuse_connection()

    def release(self, conn):
        self._return_to_pool(conn)
        self.permits.release()   # increments the counter; wakes one sleeper if any are waiting

    def _create_or_reuse_connection(self):
        conn = Connection(self.next_id)
        self.next_id += 1
        return conn

    def _return_to_pool(self, conn):
        print(f"Connection {conn.id} returned to pool")


if __name__ == "__main__":
    pool = ConnectionPool()
    conn = pool.acquire()
    print(f"Acquired connection {conn.id}")
    pool.release(conn)

