import java.util.concurrent.Semaphore;

class Connection {
    int id;
    Connection(int id) { this.id = id; }
}

class ConnectionPool {
    // starts with 10 permits, at most 10 connections checked out at once
    private final Semaphore permits = new Semaphore(10);
    private int nextId = 0;

    Connection acquire() throws InterruptedException {
        permits.acquire();   // decrements the counter; sleeps if it would go below 0
        return createOrReuseConnection();
    }

    void release(Connection conn) {
        returnToPool(conn);
        permits.release();   // increments the counter; wakes one sleeper if any are waiting
    }

    private Connection createOrReuseConnection() {
        return new Connection(nextId++);
    }

    private void returnToPool(Connection conn) {
        System.out.println("Connection " + conn.id + " returned to pool");
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        ConnectionPool pool = new ConnectionPool();
        Connection conn = pool.acquire();
        System.out.println("Acquired connection " + conn.id);
        pool.release(conn);
    }
}

