#include <bits/stdc++.h>
using namespace std;

struct Connection {
    int id;
};

class ConnectionPool {
    // starts with 10 permits, at most 10 connections checked out at once
    // (std::counting_semaphore requires C++20)
    counting_semaphore<10> permits{10};
    int nextId = 0;
public:
    Connection acquire() {
        permits.acquire();   // decrements the counter; blocks if it would go below 0
        return createOrReuseConnection();
    }

    void release(const Connection& conn) {
        returnToPool(conn);
        permits.release();   // increments the counter; wakes one waiter if any are blocked
    }

private:
    Connection createOrReuseConnection() {
        return {nextId++};
    }

    void returnToPool(const Connection& conn) {
        cout << "Connection " << conn.id << " returned to pool" << endl;
    }
};

int main() {
    ConnectionPool pool;
    Connection conn = pool.acquire();
    cout << "Acquired connection " << conn.id << endl;
    pool.release(conn);
    return 0;
}

