import threading


def run_phase_one_computation():
    print(f"{threading.current_thread().name} finished phase 1")


def run_phase_two_computation():
    print(f"{threading.current_thread().name} running phase 2")


def phase_complete():
    print("All 4 workers arrived, phase 2 begins")


if __name__ == "__main__":
    num_workers = 4
    barrier = threading.Barrier(num_workers, action=phase_complete)

    def worker():
        run_phase_one_computation()          # each worker finishes at its own pace
        barrier.wait()                        # blocks here until ALL 4 have called wait()
        run_phase_two_computation()          # only runs after everyone clears the barrier

    threads = [threading.Thread(target=worker, name=f"Worker-{i}") for i in range(num_workers)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

