import java.util.concurrent.*;

public class Main {
    static void runPhaseOneComputation() {
        System.out.println(Thread.currentThread().getName() + " finished phase 1");
    }

    static void runPhaseTwoComputation() {
        System.out.println(Thread.currentThread().getName() + " running phase 2");
    }

    public static void main(String[] args) throws InterruptedException {
        int numWorkers = 4;
        CyclicBarrier barrier = new CyclicBarrier(numWorkers,
            () -> System.out.println("All 4 workers arrived, phase 2 begins"));

        Runnable worker = () -> {
            runPhaseOneComputation();             // each worker finishes at its own pace
            try {
                barrier.await();                   // blocks here until ALL 4 have called await()
            } catch (Exception e) { throw new RuntimeException(e); }
            runPhaseTwoComputation();             // only runs after everyone clears the barrier
        };

        Thread[] threads = new Thread[numWorkers];
        for (int i = 0; i < numWorkers; i++) {
            threads[i] = new Thread(worker);
            threads[i].start();
        }
        for (Thread t : threads) t.join();
    }
}

