#include <bits/stdc++.h>
using namespace std;

void runPhaseOneComputation(int id) {
    cout << "Worker " << id << " finished phase 1" << endl;
}

void runPhaseTwoComputation(int id) {
    cout << "Worker " << id << " running phase 2" << endl;
}

int main() {
    int numWorkers = 4;
    // std::barrier requires C++20; the completion function runs once all arrive
    barrier phaseBarrier(numWorkers, []() noexcept {
        cout << "All 4 workers arrived, phase 2 begins" << endl;
    });

    vector<thread> threads;
    for (int i = 0; i < numWorkers; i++) {
        threads.emplace_back([&phaseBarrier, i]() {
            runPhaseOneComputation(i);        // each worker finishes at its own pace
            phaseBarrier.arrive_and_wait();    // blocks here until ALL 4 have arrived
            runPhaseTwoComputation(i);        // only runs after everyone clears the barrier
        });
    }
    for (auto& t : threads) t.join();
    return 0;
}
